SELECT TOP (1000) [ID], [APLID], [ItemsRequiringAttentionEV], [ReceivedCompletedPrimaryEV], [ReceivedCompletedSecondaryEV], [IsPageVisited], [CreatedBy], [ModifiedBy], [ApprovalNotificationEV], CONVERT(varchar, [CreatedDate], 120) AS [CreatedDate], CONVERT(varchar, [ModifiedDate], 120) AS [ModifiedDate], [ReceivedCompletedNewAccountsEV], [ReceivedCompletedMoneyInEV], [ReceivedCompletedStandingInstructionsEV], [ReceivedCompletedInvestmentChangesEV], [ReceivedCompletedWithdrawalsEV], [ReceivedCompletedTerminationsEV] FROM [dbo].[NotificationPreferences] WHERE id={{response_preferenceId}}